### **5. Sketchpad `onNodeDragStop` Handler**

**Lines [36247-36335]** - [compose/sketchpad/index.tsx](compose/sketchpad/index.tsx#L36247-L36335)

```typescript
const onNodeDragStop = useCallback(
  (event: any, node: DiagramNode) => {
    const finalX = node.position.x;
    const finalY = node.position.y;
    const draggedPieceId = getPieceIdFromNode(node);
    const selectedPieceIds = currentSelection?.pieces ?? [];
    const pieceIdsToUpdate = selectedPieceIds.length > 0 ? selectedPieceIds : [draggedPieceId];
    const startPos = dragStartPositionRef.current;
    dragStartPositionRef.current = null;
    const finalUpdates: Array<{ id: string; diff: any }> = [];
    const visualPositions = new Map<string, { x: number; y: number }>();

    if (design && startPos) {
      const offsetU = (finalX - startPos.x) / ICON_WIDTH;
      const offsetV = -(finalY - startPos.y) / ICON_WIDTH;

      // CRITICAL: Build flatDesign with metadata centers (absolute positions)
      // and PRESERVE connections (unlike old broken version that cleared them)
      const flatDesign = {
        ...design,
        pieces: (design.pieces ?? []).map((p) => ({
          ...p,
          center: metadata.get(p.guid)?.center ?? p.center,
        })),
      };

      const piecesDesign = { guid: "", name: "", pieces: pieceIdsToUpdate.map((g) => ({ guid: g })) } as Design;
      const dragDiff = dragPiecesInDesign(flatDesign, piecesDesign, { u: offsetU, v: offsetV });

      const pieceDiffUpdates = dragDiff.pieces?.updated ?? [];
      const connectionDiffUpdates = dragDiff.connections?.updated ?? [];

      if (pieceDiffUpdates.length > 0) {
        for (const pu of pieceDiffUpdates) {
          finalUpdates.push({ id: pu.piece.guid, diff: pu.diff });
        }
      }

      // CRITICAL: Dispatch connection updates to store
      if (connectionDiffUpdates.length > 0) {
        updateConnections?.(connectionDiffUpdates.map((cu) => ({ id: cu.connection.guid, diff: cu.diff })));
      }

      // CRITICAL: Re-flatten after applying diff to get correct visual positions
      // for ALL pieces (including descendants). This accounts for non-linear
      // scaling in flattenDesign (horizontalScale = 3.0633, radius = 2.697)
      const updatedDesign = applyDesignDiff(JSON.parse(JSON.stringify(design)), dragDiff);
      const updatedKit: Kit = { ...kit, designs: (kit.designs ?? []).map((d) => (d.guid === design.guid ? updatedDesign : d)) };
      const newMetaResult = piecesMetadata(updatedKit, design.guid);

      if (newMetaResult.ok) {
        for (const [pieceGuid, meta] of newMetaResult.change) {
          visualPositions.set(pieceGuid, {
            x: (meta.center.u ?? 0) * ICON_WIDTH,
            y: -((meta.center.v ?? 0) * ICON_WIDTH),
          });
        }
      }
    }

    if (visualPositions.size > 0) {
      setNodes((prevNodes) =>
        prevNodes.map((n) => {
          const pieceGuid = (n as any).data?.piece?.guid;
          if (!pieceGuid) return n;
          const pos = visualPositions.get(pieceGuid);
          if (!pos) return n;
          return { ...n, position: pos };
        }),
      );
    }

    if (finalUpdates.length > 0) {
      updatePieces?.(finalUpdates);
    }
  },
  [/* deps */],
);
```

**Critical Features**:
1. **Absolute positions**: Uses `metadata.get(p.guid)?.center` (not relative centers)
2. **Preserve connections**: `flatDesign` keeps original `design.connections` (not empty)
3. **Connection updates**: Dispatches `dragDiff.connections?.updated` to store
4. **Re-flatten**: Calls `piecesMetadata(updatedKit, design.guid)` after applying diff
5. **Visual update**: Uses re-flattened positions for all pieces (root + descendants)

